_SUSPENSIONS = (SUSPEND_THROUGH, SUSPEND_BEFORE, SUSPEND_STATUS)
_ENDS = (END_INCLUSIVE, END_EXCLUSIVE)
_DELEGATIONS = (DELEGATE_ALL, DELEGATE_OWNED, DELEGATE_NONE)


def _listed(value, allowed) -> bool:
    return isinstance(value, str) and value in allowed


@dataclass(frozen=True)
class Rules:
    roles: str
    suspension: str
    ends: str
    delegation: str
    blank_team: bool
    wildcard_admin: bool

    def __post_init__(self):
        if not _listed(self.roles, _ROLES):
            raise ValueError(f"bad roles: {self.roles!r}")
        if not _listed(self.suspension, _SUSPENSIONS):
            raise ValueError(f"bad suspension: {self.suspension!r}")
        if not _listed(self.ends, _ENDS):
            raise ValueError(f"bad ends: {self.ends!r}")
        if not _listed(self.delegation, _DELEGATIONS):
            raise ValueError(f"bad delegation: {self.delegation!r}")
        if type(self.blank_team) is not bool:
            raise ValueError(f"bad blank_team: {self.blank_team!r}")
        if type(self.wildcard_admin) is not bool:
            raise ValueError(f"bad wildcard_admin: {self.wildcard_admin!r}")


