    return False


def can_delete(store: Store, user_id: str, doc: Doc, at: datetime, rules: Rules) -> bool:
    user, people, carriers = _setup(store, user_id, at, rules)
    if user is None:
        return False
    for person in people:
        if doc.owner == person.id:
            return True
        if person in carriers and _by_role(person, "admin", rules):
